it('compiles each dynamic schema once and validates the current definition', async () => {
  const registry = new ToolRegistry();
  const compile = jest.spyOn(Ajv.prototype, 'compile');
  const stringSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
  const numberSchema = {type: 'object', properties: {location: {type: 'number'}}, required: ['location']};
  let inputSchema = stringSchema;
  let executions = 0;
  registry.register(
    () => ({name: 'weather', description: 'Weather lookup', inputSchema}),
    async () => {
      executions++;
      return 'forecast';
    }
  );

  try {
    const first = await registry.execute('weather', {location: 'Berlin'});
    inputSchema = numberSchema;
    const second = await registry.execute('weather', {location: 'Berlin'});
    inputSchema = stringSchema;
    const third = await registry.execute('weather', {location: 'Berlin'});

    const {calls} = compile.mock;
    expect({first, second, third, executions, compilations: calls.length}).toEqual({
      first: {result: 'forecast'},
      second: {result: expect.stringMatching(/location.*number/)},
      third: {result: 'forecast'},
      executions: 2,
      compilations: 2,
    });
  } finally {
    compile.mockRestore();
  }
});
